/**
 * Entry point: a Node.js port of `test8.py`.
 *
 *     import argparse
 *     from jose import jwt
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--payload', type=str, required=True)
 *     parser.add_argument('--secret', type=str, required=True)
 *     args = parser.parse_args()
 *
 *     secret = args.secret
 *     payload = {"data": args.payload}
 *
 *     token = jwt.encode(payload, secret)
 *     print(token)
 *     claims = jwt.get_unverified_claims(token)
 *     print(claims)
 *     header = jwt.get_unverified_header(token)
 *     print(header)
 */

import { jwt } from './lib/index.mjs';
import { ArgumentParser } from './lib/python/argparse.mjs';
import { repr } from './lib/python/repr.mjs';

/**
 * `print(...)`: write the text plus a newline straight to stdout, with no
 * inspection or format-specifier handling.
 *
 * @param {string} text
 */
function print(text) {
  process.stdout.write(text + '\n');
}

/**
 * The reference build reports itself as `test8_executable` in usage and error
 * messages, because that is the basename of its `sys.argv[0]`. Pinning `prog`
 * keeps the diagnostics identical rather than leaking this file's name.
 */
const PROG = 'test8_executable';

export function main(argv = process.argv.slice(2)) {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--payload'], { required: true });
  parser.addArgument(['--secret'], { required: true });
  const args = parser.parseArgs(argv);

  const secret = args.secret;
  const payload = new Map([['data', args.payload]]);

  const token = jwt.encode(payload, secret);
  print(token);

  const claims = jwt.getUnverifiedClaims(token);
  print(repr(claims));

  const header = jwt.getUnverifiedHeader(token);
  print(repr(header));
}

main();
