  // bit length. The expression yields 1..64, so the 0x80 byte always fits.
  const bitLength = message.length * 8;
  const padLength = SHA256_BLOCK_SIZE - ((message.length + 8) % SHA256_BLOCK_SIZE);

  const padded = new Uint8Array(message.length + padLength + 8);
