  padded[tail + 1] = (hi >>> 16) & 0xff;
  padded[tail + 2] = (hi >>> 8) & 0xff;
  padded[tail + 3] = hi & 0xff;
  padded[tail + 4] = (lo >>> 24) & 0xff;
  padded[tail + 5] = (lo >>> 16) & 0xff;
  padded[tail + 6] = (lo >>> 8) & 0xff;
