/**
 * Byte-level primitives.
 *
 * Everything downstream (SHA-256, HMAC, base64url) works on `Uint8Array`, so
 * this module owns the single place where JavaScript's UTF-16 strings are
 * turned into the UTF-8 octets CPython would have produced for `str.encode()`.
 */

/**
 * Encode a string as UTF-8 octets.
 *
 * Unpaired surrogates cannot survive a round trip through UTF-8, so they are
 * replaced with U+FFFD -- the same substitution the platform's own encoder
 * performs.
 *
 * @param {string} str
 * @returns {Uint8Array}
 */
export function utf8Encode(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let cp = str.charCodeAt(i);

    if (cp >= 0xd800 && cp <= 0xdbff) {
      const next = i + 1 < str.length ? str.charCodeAt(i + 1) : 0;
      if (next >= 0xdc00 && next <= 0xdfff) {
        cp = (cp - 0xd800) * 0x400 + (next - 0xdc00) + 0x10000;
        i++;
      } else {
        cp = 0xfffd;
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = 0xfffd;
    }

    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return Uint8Array.from(out);
}

/**
 * Decode UTF-8 octets back into a string. Malformed sequences become U+FFFD.
 *
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function utf8Decode(bytes) {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const b0 = bytes[i];
    let cp;
    let width;

    if (b0 < 0x80) {
      cp = b0;
      width = 1;
    } else if ((b0 & 0xe0) === 0xc0) {
      cp = b0 & 0x1f;
      width = 2;
    } else if ((b0 & 0xf0) === 0xe0) {
      cp = b0 & 0x0f;
      width = 3;
    } else if ((b0 & 0xf8) === 0xf0) {
      cp = b0 & 0x07;
      width = 4;
    } else {
      out += '�';
      i++;
      continue;
    }

    if (i + width > bytes.length) {
      out += '�';
      i++;
      continue;
    }

    let valid = true;
    for (let k = 1; k < width; k++) {
      const bk = bytes[i + k];
      if ((bk & 0xc0) !== 0x80) {
        valid = false;
        break;
      }
      cp = (cp << 6) | (bk & 0x3f);
    }

    // Reject over-long encodings, surrogates and out-of-range code points.
    const minimum = [0, 0, 0x80, 0x800, 0x10000][width];
    if (!valid || cp < minimum || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
      out += '�';
      i++;
      continue;
    }

    out += String.fromCodePoint(cp);
    i += width;
  }
  return out;
}

/**
 * Constant-space equality check over two byte arrays.
 *
 * @param {Uint8Array} a
 * @param {Uint8Array} b
 * @returns {boolean}
 */
export function bytesEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

/**
 * Concatenate byte arrays.
 *
 * @param {...Uint8Array} chunks
 * @returns {Uint8Array}
 */
export function concatBytes(...chunks) {
  let total = 0;
  for (const c of chunks) total += c.length;
  const out = new Uint8Array(total);
  let offset = 0;
  for (const c of chunks) {
    out.set(c, offset);
    offset += c.length;
  }
  return out;
}

