#!/usr/bin/env node
/**
 * (a) Known-answer tests for the hand-written SHA-256 / HMAC-SHA256.
 *
 * Vectors: FIPS 180-4 / NIST SHA-256 examples and RFC 4231 HMAC-SHA256
 * test cases 1..7.
 */

import { sha256, toHex, hmacSha256 } from '/output/lib/index.mjs';

const enc = (s) => {
  const out = [];
  for (let i = 0; i < s.length; i++) out.push(s.charCodeAt(i) & 0xff);
  return Uint8Array.from(out);
};
const rep = (byte, n) => new Uint8Array(n).fill(byte);
const hexToBytes = (h) => Uint8Array.from(h.match(/../g).map((p) => parseInt(p, 16)));

let run = 0;
const failures = [];
function check(name, expected, actual, extra = {}) {
  run++;
  if (expected.toLowerCase() !== actual.toLowerCase()) {
    failures.push({ name, expected, actual, ...extra });
  }
}

// ------------------------------------------------------------------ SHA-256
const S448 = 'abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq';
const S896 =
  'abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmnhijklmno' +
  'ijklmnopjklmnopqklmnopqrlmnopqrsmnopqrstnopqrstu';

const shaVectors = [
  ['SHA-256 empty string (FIPS 180-4)', '', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'],
  ['SHA-256 "abc" (FIPS 180-4 B.1)', 'abc', 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad'],
  ['SHA-256 448-bit message (FIPS 180-4 B.2)', S448, '248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1'],
  ['SHA-256 896-bit message (FIPS 180-4)', S896, 'cf5b16a778af8380036ce59e7b0492370b249b11e8f07a51afac45037afee9d1'],
  ['SHA-256 one million "a" (FIPS 180-4 B.3)', 'a'.repeat(1000000), 'cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0'],
];

for (const [name, msg, expected] of shaVectors) {
  check(name, expected, toHex(sha256(enc(msg))), { inputLength: msg.length });
}

// Extra published extension: "abcdefghij" repeated 1e6/10 -> also known.
// (skipped: not a FIPS vector)

// ------------------------------------------------------------- HMAC-SHA256
const hmacVectors = [
  {
    name: 'RFC 4231 case 1',
    key: rep(0x0b, 20),
    data: enc('Hi There'),
    mac: 'b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7',
  },
  {
    name: 'RFC 4231 case 2 (short key "Jefe")',
    key: enc('Jefe'),
    data: enc('what do ya want for nothing?'),
    mac: '5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843',
  },
  {
    name: 'RFC 4231 case 3 (20-byte 0xaa key, 50 x 0xdd)',
    key: rep(0xaa, 20),
    data: rep(0xdd, 50),
    mac: '773ea91e36800e46854db8ebd09181a72959098b3ef8c122d9635514ced565fe',
  },
  {
    name: 'RFC 4231 case 4 (25-byte incrementing key, 50 x 0xcd)',
    key: hexToBytes('0102030405060708090a0b0c0d0e0f10111213141516171819'),
    data: rep(0xcd, 50),
    mac: '82558a389a443c0ea4cc819899f2083a85f0faa3e578f8077a2e3ff46729665b',
  },
  {
    name: 'RFC 4231 case 5 (truncation vector, full 256-bit MAC)',
    key: rep(0x0c, 20),
    data: enc('Test With Truncation'),
    mac: 'a3b6167473100ee06e0c796c2955552bfa6f7c0a6a8aef8b93f860aab0cd20c5',
  },
  {
    name: 'RFC 4231 case 6 (131-byte key > block size)',
    key: rep(0xaa, 131),
    data: enc('Test Using Larger Than Block-Size Key - Hash Key First'),
    mac: '60e431591ee0b67f0d8a26aacbf5b77f8e0bc6213728c5140546040f0ee37f54',
  },
  {
    name: 'RFC 4231 case 7 (131-byte key, 152-byte data)',
    key: rep(0xaa, 131),
    data: enc(
      'This is a test using a larger than block-size key and a larger ' +
        'than block-size data. The key needs to be hashed before being ' +
        'used by the HMAC algorithm.',
    ),
    mac: '9b09ffa71b942fcb27635fbcd5b0e944bfdc63644f0713938a7f51535c3a35e2',
  },
];

for (const v of hmacVectors) {
  check(v.name, v.mac, toHex(hmacSha256(v.key, v.data)), {
    keyLength: v.key.length,
    dataLength: v.data.length,
  });
}

// RFC 4231 case 5 also specifies HMAC-SHA-256-128 (first 128 bits).
check(
  'RFC 4231 case 5 truncated to 128 bits (HMAC-SHA-256-128)',
  'a3b6167473100ee06e0c796c2955552b',
  toHex(hmacSha256(rep(0x0c, 20), enc('Test With Truncation')).slice(0, 16)),
);

// Boundary keys around the 64-byte HMAC key-normalization edge, cross-checked
// against the RFC 2104 construction expressed independently via sha256().
function hmacReference(key, message) {
  const k = key.length > 64 ? sha256(key) : key;
  const block = new Uint8Array(64);
  block.set(k, 0);
  const ipad = new Uint8Array(64);
  const opad = new Uint8Array(64);
  for (let i = 0; i < 64; i++) {
    ipad[i] = block[i] ^ 0x36;
    opad[i] = block[i] ^ 0x5c;
  }
  const inner = new Uint8Array(64 + message.length);
  inner.set(ipad, 0);
  inner.set(message, 64);
  const id = sha256(inner);
  const outer = new Uint8Array(64 + 32);
  outer.set(opad, 0);
  outer.set(id, 64);
  return sha256(outer);
}
for (const kl of [0, 1, 31, 32, 55, 56, 63, 64, 65, 66, 127, 128, 129]) {
  for (const dl of [0, 1, 55, 56, 63, 64, 65, 119, 120]) {
    const key = new Uint8Array(kl).map((_, i) => (i * 7 + 3) & 0xff);
    const data = new Uint8Array(dl).map((_, i) => (i * 31 + 17) & 0xff);
    check(
      `RFC 2104 construction cross-check key=${kl} data=${dl}`,
      toHex(hmacReference(key, data)),
      toHex(hmacSha256(key, data)),
    );
  }
}

console.log(JSON.stringify({ run, failures }, null, 2));
process.exit(failures.length === 0 ? 0 : 1);

#!/usr/bin/env node
/**
 * (b) Differential length sweep: reference build vs. Node port over payload and
 * secret byte-lengths 0..300, in both ASCII-only and multi-byte UTF-8 flavours,
 * plus a random sample of (payloadLen, secretLen) combinations.
 *
 * Targets SHA-256 padding boundaries (55/56/63/64 mod 64) and the HMAC
 * key-normalization boundary at 64 bytes.
 */

import { spawn } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test8_executable';
const PORT = '/output/test8.mjs';
const MAX_LEN = 300;
const CONCURRENCY = 12;

// ------------------------------------------------------------ string builders
const utf8Len = (s) => Buffer.byteLength(s, 'utf8');

/** ASCII filler of exactly n bytes; never starts with '-'. */
function asciiOfBytes(n) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.';
  let s = '';
  for (let i = 0; i < n; i++) s += alphabet[i % alphabet.length];
  return s;
}

/**
 * A string whose UTF-8 encoding is exactly n bytes, mixing 1-, 2-, 3- and
 * 4-byte code points so that byte length differs from character length.
 * Deterministic in (n, seed).
 */
function mixedOfBytes(n, seed = 0) {
  const pool = [
    ['a', 1], ['Z', 1], ['7', 1], ['_', 1],
    ['é', 2], ['ÿ', 2], ['Ω', 2], ['א', 2],
    ['你', 3], ['こ', 3], ['€', 3], ['�', 3],
    ['\u{1f600}', 4], ['\u{2070e}', 4], ['\u{10ffff}', 4], ['\u{1d11e}', 4],
  ];
  const ones = pool.filter(([, w]) => w === 1);
  let s = '';
  let left = n;
  let i = seed;
  // Leading char is always ASCII-safe so argparse never sees a leading '-'.
  while (left > 0) {
    const candidates = pool.filter(([, w]) => w <= left);
    // Prefer variety, but guarantee an exact fit: if only 1 byte remains the
    // filter above already restricts us to single-byte code points.
    const [ch, w] = candidates[i % candidates.length];
    // Avoid trapping ourselves: leaving exactly 1..3 bytes is always fillable
    // because single-byte code points exist in the pool.
    s += ch;
    left -= w;
    i += 5;
    if (left === 0) break;
    if (candidates.length === 1 && w === 1 && left > 0) {
      s += ones[0][0].repeat(left);
      left = 0;
    }
  }
  if (utf8Len(s) !== n) throw new Error(`builder bug: want ${n} got ${utf8Len(s)}`);
  return s;
}

// ------------------------------------------------------------------ the cases
/** @type {{argv:string[], label:string}[]} */
const cases = [];
const push = (label, payload, secret) =>
  cases.push({ argv: ['--payload', payload, '--secret', secret], label });

// Sweep 1: payload byte-length 0..300, ASCII, secret fixed.
for (let n = 0; n <= MAX_LEN; n++) {
  push(`payload ascii ${n}B / secret 1B`, asciiOfBytes(n), 'k');
}
// Sweep 2: payload byte-length 0..300, multi-byte UTF-8, secret fixed.
for (let n = 0; n <= MAX_LEN; n++) {
  push(`payload utf8 ${n}B / secret 1B`, mixedOfBytes(n, n), 'k');
}
// Sweep 3: secret byte-length 0..300, ASCII, payload fixed.
for (let n = 0; n <= MAX_LEN; n++) {
  push(`payload 1B / secret ascii ${n}B`, 'p', asciiOfBytes(n));
}
// Sweep 4: secret byte-length 0..300, multi-byte UTF-8, payload fixed.
for (let n = 0; n <= MAX_LEN; n++) {
  push(`payload 1B / secret utf8 ${n}B`, 'p', mixedOfBytes(n, n * 3 + 1));
}

// Combination grid over the interesting residues mod 64 in both dimensions.
const EDGES = [0, 1, 2, 53, 54, 55, 56, 57, 62, 63, 64, 65, 66, 117, 118, 119, 120, 121, 127, 128, 129, 191, 192, 193, 255, 256, 300];
for (const p of EDGES) {
  for (const s of EDGES) {
    push(`edge grid payload ${p}B / secret ${s}B (utf8)`, mixedOfBytes(p, p + s), mixedOfBytes(s, s * 7 + p));
  }
}

// Deterministic pseudo-random sample of combinations across 0..300.
let rngState = 0x2f6e2b1;
const rnd = () => {
  rngState = (rngState * 1103515245 + 12345) & 0x7fffffff;
  return rngState / 0x80000000;
};
for (let i = 0; i < 250; i++) {
  const p = Math.floor(rnd() * (MAX_LEN + 1));
  const s = Math.floor(rnd() * (MAX_LEN + 1));
  const mixed = rnd() < 0.5;
  push(
    `random payload ${p}B / secret ${s}B (${mixed ? 'utf8' : 'ascii'})`,
    mixed ? mixedOfBytes(p, i) : asciiOfBytes(p),
    mixed ? mixedOfBytes(s, i + 97) : asciiOfBytes(s),
  );
}

// ---------------------------------------------------------------- the running
/** @param {string} cmd @param {string[]} argv */
function run(cmd, argv) {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, argv, { stdio: ['ignore', 'pipe', 'pipe'] });
    const out = [];
    const err = [];
    child.stdout.on('data', (d) => out.push(d));
    child.stderr.on('data', (d) => err.push(d));
    child.on('error', reject);
    child.on('close', (code, signal) =>
      resolve({ out: Buffer.concat(out), err: Buffer.concat(err), code, signal }),
    );
  });
}

const show = (buf) => JSON.stringify(buf.toString('utf8'));

const failures = [];
let done = 0;

async function worker(queue) {
  for (;;) {
    const item = queue.pop();
    if (!item) return;
    const [ref, port] = await Promise.all([
      run(REFERENCE, item.argv),
      run(process.execPath, [PORT, ...item.argv]),
    ]);
    const same =
      ref.code === port.code &&
      Buffer.compare(ref.out, port.out) === 0 &&
      Buffer.compare(ref.err, port.err) === 0;
    if (!same) {
      failures.push({
        label: item.label,
        argvJson: JSON.stringify(item.argv),
        referenceOutput: `exit=${ref.code} stdout=${show(ref.out)} stderr=${show(ref.err)}`,
        portOutput: `exit=${port.code} stdout=${show(port.out)} stderr=${show(port.err)}`,
      });
    }
    done++;
    if (done % 200 === 0) process.stderr.write(`  ...${done}/${cases.length}\n`);
  }
}

const queue = cases.slice().reverse();
await Promise.all(Array.from({ length: CONCURRENCY }, () => worker(queue)));

console.log(JSON.stringify({ casesRun: done, failures }, null, 2));
process.exit(failures.length === 0 ? 0 : 1);

